using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 RescueDog Dog=>game.World.Changes.Dog??=new();
 Infected rescueDogActor;int rescueDogSeed=int.MinValue;double dogBark,dogBite,dogSave,dogWhine;
 bool DogPresent=>rescueDogActor!=null&&GodotObject.IsInstanceValid(rescueDogActor.Body)&&rescueDogSeed==game.Save.Seed;
 Vector3 DogPoint=>new((float)Dog.X,(float)Dog.Y,(float)Dog.Z);
 void DrawRescueDog(double dt){if(!LivingEnabled)return;SpawnDogRescue();if(rescueDogActor!=null&&GodotObject.IsInstanceValid(rescueDogActor.Body)&&rescueDogSeed!=game.Save.Seed){rescueDogActor.Body.QueueFree();rescueDogActor=null;}

  if(DogPresent&&(dungeon!=null||!(CoopHost?NearActiveSurface(DogPoint,210):Distance(player.Position,DogPoint)<210)||rescueDogSeed!=game.Save.Seed)){rescueDogActor.Body.QueueFree();rescueDogActor=null;}
  if(dungeon!=null||!Dog.Initialized||!(CoopHost?NearActiveSurface(DogPoint,190):Distance(player.Position,DogPoint)<190))return;
  if(!DogPresent){if(rescueDogActor!=null&&GodotObject.IsInstanceValid(rescueDogActor.Body))rescueDogActor.Body.QueueFree();var body=new CharacterBody3D{Name="RescueDog",Position=DogPoint,CollisionLayer=2,CollisionMask=1,FloorSnapLength=.5f};body.AddChild(new CollisionShape3D{Position=new(0,.4f,0),Shape=new CapsuleShape3D{Radius=.25f,Height=.8f}});var art=new Node3D();body.AddChild(art);AnimalArt(art,"companion");Box(art,new(0,.68f,-.38f),new(.40f,.06f,.10f),new(.18f,.38f,.56f));body.AddChild(new Label3D{Name="DogLabel",Position=new(0,1.35f,0),FontSize=22,PixelSize=.005f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});AddChild(body);rescueDogActor=new(){Id="companion/dog",Body=body,Visual=art,Home=DogPoint};rescueDogSeed=game.Save.Seed;}
  if(CoopClient)rescueDogActor.Body.Position=rescueDogActor.Body.Position.Lerp(DogPoint,(float)Math.Min(1,dt*12));
  rescueDogActor.Body.Visible=Distance(player.Position,DogPoint)<180;rescueDogActor.Body.GetNode<Label3D>("DogLabel").Text=Dog.Dead?(Dog.Name==""?"THE RESCUE DOG":Dog.Name)+" / GONE":(Dog.Name==""?"STRAY DOG":Dog.Name)+$" / HP {Dog.Health:0} / {Dog.Mode.ToUpperInvariant()}";
  rescueDogActor.Visual.Rotation=Dog.Dead?new(0,0,Mathf.Pi/2):Vector3.Zero;
  if(!Dog.Dead)for(int i=0;i<4;i++)rescueDogActor.Visual.GetNode<Node3D>("Leg"+i).RotationDegrees=new((float)Math.Sin(game.Clock*9+i%2*Math.PI)*(rescueDogActor.Body.Velocity.Length()>1?25:0),0,0);
 }
 void TickRescueDog(double dt){if(!LivingEnabled||CoopClient||dungeon!=null||Dog.Dead||!Dog.Rescued||!DogPresent)return;
  var leader=CommunityLeader(Dog.Owner);if(leader==null)return;var body=rescueDogActor.Body;float ownerDistance=Distance(body.Position,leader.Value.Body.Position);bool near=ownerDistance<18;
  if(near){Dog.Together+=dt;Dog.Bond=Math.Min(100,Dog.Bond+dt/120);if(leader.Value.Game.Sneaking)Dog.Training=Math.Min(100,Dog.Training+dt/18);}
  dogBark-=dt;if(dogBark<=0){dogBark=18+Dog.Training*.6;if(Dog.Training<90){HearNoise(body.Position,Dog.NoiseRadius);game.Notice=(Dog.Name==""?"The dog":Dog.Name)+" barks / infected can hear it";EnemySound(body.Position,4);}}
  dogBite=Math.Max(0,dogBite-dt);var threats=(dogPackSource??infected).Where(e=>!Peaceful(e.Id)&&!PassiveStoryEnemy(e)&&!DormantWeeper(e)&&Distance(e.Body.Position,body.Position)<(Dog.Mode=="recall"||Dog.Mode=="stay"?1.7:Dog.Training<35?13:7)).OrderBy(e=>Distance(e.Body.Position,body.Position));var target=threats.FirstOrDefault();
  Vector3 goal=Dog.Mode=="stay"?body.Position:leader.Value.Body.Position+leader.Value.Body.Basis.X*1.8f;
  if(target!=null&&Dog.Mode!="recall"){goal=target.Body.Position;if(Distance(goal,body.Position)<1.65&&dogBite<=0&&PursuitClear(body.Position,goal,PursuitExclusions())){dogBite=1.8;target.Hp-=22;if(target.Hp<=0){KillEnemy(target);Dog.Bond=Math.Min(100,Dog.Bond+1);}}}
  var direction=PursuitDirection(rescueDogActor,goal,dt);var velocity=direction.Length()>1.1?direction.Normalized()*(leader.Value.Game.Sneaking?1.4f:target==null&&ownerDistance>8?(float)Math.Max(10.5,10.5*leader.Value.Game.Speed):6.5f):Vector3.Zero;velocity.Y=body.IsOnFloor()?-.1f:body.Velocity.Y-18*(float)dt;body.Velocity=velocity;body.MoveAndSlide();if(direction.LengthSquared()>.01)body.Rotation=new(0,Mathf.Atan2(-direction.X,-direction.Z),0);Dog.X=body.Position.X;Dog.Y=body.Position.Y;Dog.Z=body.Position.Z;
  if(Dog.Health<30&&(dogWhine-=dt)<=0){dogWhine=12;game.Notice="Your dog is badly hurt / recall it and retreat!";}
  if(near&&target==null)Dog.Health=Math.Min(100,Dog.Health+dt*.12);if((dogSave-=dt)<=0){dogSave=10;game.Persist();}
 }
 bool DogCanBeTarget(Infected e,float playerDistance){return dungeon==null&&Dog.Rescued&&!Dog.Dead&&DogPresent&&Distance(e.Body.Position,DogPoint)<Math.Min(20,playerDistance)&&PursuitClear(e.Body.Position,DogPoint,PursuitExclusions());}
 void HurtRescueDog(double damage){if(Dog.Dead)return;Dog.Hurt(damage);if(Dog.Dead){game.Life.Morale=Math.Max(0,game.Life.Morale-25);game.WorldDecision("dog/death",(Dog.Name==""?"The dog":Dog.Name)+" died here. There will not be another.");game.Persist();FeverSync();}}
 bool DogNear=>dungeon==null&&Dog.Initialized&&Distance(player.Position,DogPoint)<3.5f;
 string RescueDogPrompt()=>DogNear?"F / "+(Dog.Dead?"REMEMBER YOUR DOG":Dog.Rescued?"DOG / CARE AND COMMANDS":"A FRIGHTENED DOG / RESCUE"):"";
 bool RescueDogInteract(){if(!LivingEnabled||!DogNear)return false;ShowDog();return true;}
 void DogAction(string data){if(CoopClient||Dog.Dead||data.Length>64||dungeon!=null)return;string op=data.Split('|')[0];bool command=op is "follow" or "stay" or "recall";if(command?(!Dog.Rescued||Dog.Owner!=CommunityOwner||Distance(player.Position,DogPoint)>100):!DogNear)return;if(!Dog.Rescued){if(op!="rescue"||game.Life.Food<1)return;if(!KennelClear){game.Notice="Clear the infected from the kennel yard before opening the run";return;}game.Change(()=>{game.Life.Food--;Dog.Rescued=true;Dog.Owner=CommunityOwner;Dog.Bond=5;OpenRescueKennel();});}else{if(Dog.Owner!=CommunityOwner){game.Notice="This dog trusts another survivor / they give the commands";return;}if(op=="name"&&Dog.NameReady&&Dog.Name==""){string name=data.Length>5?data.Substring(5).Trim():"";if(name.Length<1||name.Length>24||name.Any(char.IsControl))return;game.Change(()=>Dog.Name=name);}else if(op is "follow" or "stay" or "recall")game.Change(()=>Dog.Mode=op);else if(op=="care"&&game.Life.Food>0&&game.World.Changes.Time>=Dog.CareAt)game.Change(()=>{game.Life.Food--;Dog.Health=Math.Min(100,Dog.Health+15);Dog.Bond=Math.Min(100,Dog.Bond+3);Dog.CareAt=game.World.Changes.Time+300;});}FeverSync();}
 void ShowDog(){var b=Panel("ONE DOG / A FRIEND YOU CAN LOSE");Text(b,Dog.Dead?"It is quiet now. This dog will not respawn.":$"Health {Dog.Health:0}/100 / Bond {Dog.Bond:0}/100 / Stealth {Dog.Training:0}/100\nBark radius {Dog.NoiseRadius:0}m. Early curiosity draws it into danger. Train by sneaking together. Commands work within 100m; care needs you beside it. No combat teleport or resurrection. Waits outside dungeons.");void Act(string label,string op){Button(b,label,()=>{if(!CoopRequest("dog",op))DogAction(op);ShowDog();});}if(!Dog.Dead){if(!Dog.Rescued)Act(KennelClear?"OPEN THE RUN / GAIN ITS TRUST / 1 FOOD":"KENNEL GUARDED / CLEAR THE YARD FIRST","rescue");else{Act("FOLLOW / DEFEND","follow");Act("STAY / HOLD POSITION","stay");Act("RECALL / DISENGAGE","recall");Act("FEED AND TEND / 1 FOOD, 5 MIN COOLDOWN","care");if(Dog.Name==""&&Dog.NameReady){var input=new LineEdit{PlaceholderText="Give your friend a name",MaxLength=24};b.AddChild(input);Button(b,"NAME YOUR DOG",()=>{string op="name|"+input.Text;if(!CoopRequest("dog",op))DogAction(op);ShowDog();});}else if(Dog.Name=="")Text(b,"Naming unlocks after 15 active minutes together and bond 15.");}}Text(b,game.Notice);Button(b,"BACK",CloseMenu);}
}
